"""Emit the PHP resource layer (PSR-4, namespace Tino\\UserApi\\Resources)."""
from __future__ import annotations

import os
from typing import Any, Dict, List

from . import catalog as cat

HEADER = """<?php

declare(strict_types=1);

/**
 * {title}.
 *
 * Generated from spec/tino-userapi-catalog.json by tools/generate-sdk.py — do not edit by hand.
 */

namespace Tino\\UserApi\\Resources;

/**
 * {title} — {count} operations.
 */
class {class_name} extends Resource
{{"""


def _docblock(operation: Dict[str, Any]) -> List[str]:
    lines = ["    /**"]
    for line in cat.doc_lines(operation):
        lines.append(("     * " + line).rstrip())
    lines.append("     *")
    for param in cat.path_params(operation):
        description = (param.get("description") or "").replace("\n", " ")
        lines.append(f"     * @param string|int ${cat.php_arg(param['name'])} {description}".rstrip())
    if cat.has_body(operation):
        lines.append("     * @param array<string,mixed> $body Request payload.")
    lines.append("     * @param array<string,mixed> $query Extra query-string parameters.")
    lines.append("     *")
    lines.append("     * @return mixed Decoded response body.")
    lines.append("     */")
    return lines


def _method(operation: Dict[str, Any]) -> List[str]:
    name = cat.camel(operation["name"])
    params = cat.path_params(operation)
    args = [f"${cat.php_arg(p['name'])}" for p in params]
    if cat.has_body(operation):
        args.append("array $body = []")
    args.append("array $query = []")

    lines = _docblock(operation)
    lines.append(f"    public function {name}({', '.join(args)})")
    lines.append("    {")

    if params:
        mapping = ", ".join(f"'{p['name']}' => ${cat.php_arg(p['name'])}" for p in params)
        lines.append(f"        $path = $this->path('{operation['path']}', [{mapping}]);")
        path_expr = "$path"
    else:
        path_expr = f"'{operation['path']}'"

    options = ["'query' => $query"]
    if cat.has_body(operation):
        options.append("'body' => $body")
    if not operation.get("auth", True):
        options.append("'authenticated' => false")
    lines.append(
        f"        return $this->call('{operation['method']}', {path_expr}, [" + ", ".join(options) + "]);"
    )
    lines.append("    }")
    lines.append("")
    return lines


def emit(catalog: Dict[str, Any], root: str) -> List[str]:
    grouped = cat.by_group(catalog)
    out_dir = os.path.join(root, "sdk", "php", "src", "Resources")
    os.makedirs(out_dir, exist_ok=True)
    written: List[str] = []

    for group, operations in sorted(grouped.items()):
        class_name = cat.pascal(group)
        title = cat.GROUP_TITLES.get(group, group)
        lines = [HEADER.format(title=title, class_name=class_name, count=len(operations))]
        for operation in operations:
            lines.extend(_method(operation))
        lines.append("}")
        path = os.path.join(out_dir, class_name + ".php")
        with open(path, "w", encoding="utf-8") as handle:
            handle.write("\n".join(lines).rstrip() + "\n")
        written.append(path)

    registry = [
        "<?php",
        "",
        "declare(strict_types=1);",
        "",
        "/**",
        " * Map of client property name => resource class.",
        " *",
        " * Generated by tools/generate-sdk.py — do not edit by hand.",
        " */",
        "",
        "namespace Tino\\UserApi\\Resources;",
        "",
        "final class ResourceRegistry",
        "{",
        "    /** @var array<string,class-string<Resource>> */",
        "    public const CLASSES = [",
    ]
    for group in sorted(grouped):
        registry.append(f"        '{cat.camel(group)}' => {cat.pascal(group)}::class,")
    registry.append("    ];")
    registry.append("}")
    registry_path = os.path.join(out_dir, "ResourceRegistry.php")
    with open(registry_path, "w", encoding="utf-8") as handle:
        handle.write("\n".join(registry) + "\n")
    written.append(registry_path)
    return written
